# P2.7 coefficient polynomials
def AA(n):
    n = QQ(n)
    return (_sage_const_1024 *(_sage_const_2 *n+_sage_const_5 )**_sage_const_4 *(_sage_const_2 *n+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *n+_sage_const_9 )**_sage_const_3 
            *(_sage_const_946 *n**_sage_const_2  + _sage_const_6407 *n + _sage_const_10860 ))

def BB(n):
    n = QQ(n)
    return (_sage_const_128 *(_sage_const_2 *n+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *n+_sage_const_9 )**_sage_const_3 
            *(_sage_const_104060 *n**_sage_const_6  + _sage_const_1745370 *n**_sage_const_5  + _sage_const_12145238 *n**_sage_const_4 
              + _sage_const_44886481 *n**_sage_const_3  + _sage_const_92943995 *n**_sage_const_2 
              + _sage_const_102256019 *n + _sage_const_46709052 ))

def CC(n):
    n = QQ(n)
    return (_sage_const_16 *(n+_sage_const_3 )**_sage_const_4 *(_sage_const_2 *n+_sage_const_9 )**_sage_const_3 
            *(_sage_const_3784 *n**_sage_const_5  + _sage_const_57792 *n**_sage_const_4  + _sage_const_351019 *n**_sage_const_3 
              + _sage_const_1059230 *n**_sage_const_2  + _sage_const_1587211 *n + _sage_const_944620 ))

def DD(n):
    n = QQ(n)
    return ((n+_sage_const_3 )**_sage_const_4 *(n+_sage_const_4 )**_sage_const_6 
            *(_sage_const_946 *n**_sage_const_2  + _sage_const_4515 *n + _sage_const_5399 ))

# CORRECT forward recurrence (proof.tex eq:rec)
# u_{n+1} = B(n)/A(n) u_n - C(n-1)/A(n-1) u_{n-1} + D(n-2)/A(n-2) u_{n-2}
def alpha(n): return BB(n) / AA(n)
def beta(n): return -CC(n-_sage_const_1 ) / AA(n-_sage_const_1 )
def gamma(n): return DD(n-_sage_const_2 ) / AA(n-_sage_const_2 )

def target_q(N):
    q = [
        QQ(-_sage_const_215040420000 ),
        QQ(-_sage_const_167282265043404 ) / QQ(_sage_const_905 ),
        QQ(-_sage_const_964185327658080 ) / QQ(_sage_const_6071 ),
    ]
    for n in range(_sage_const_2 , N - _sage_const_1 ):
        q.append(alpha(n)*q[n] + beta(n)*q[n-_sage_const_1 ] + gamma(n)*q[n-_sage_const_2 ])
    return q[:N]

# Harmonic sums
def H(k, r):
    return sum(QQ(_sage_const_1 ) / j**r for j in range(_sage_const_1 , k + _sage_const_1 ))

# AESZ #209 inner polynomial
def aesz_poly(n):
    return sum(
        binomial(n, k)**_sage_const_2 
        * binomial(n + k, n)
        * binomial(n + _sage_const_2 *k, n)
        * t**k
        for k in range(n + _sage_const_1 )
    )

# Cauchy twist coefficients (tau=1)
def cauchy_twist_coeffs(N, tau=QQ(_sage_const_1 )):
    c = [QQ(_sage_const_1 )]
    for r in range(N - _sage_const_1 ):
        c1 = c[r - _sage_const_1 ] if r >= _sage_const_1  else QQ(_sage_const_0 )
        c2 = c[r - _sage_const_2 ] if r >= _sage_const_2  else QQ(_sage_const_0 )
        num = ((_sage_const_440 *r + _sage_const_660 *tau) * c[r]
               + (_sage_const_144 *tau - _sage_const_16 *r + _sage_const_16 ) * c1
               + (_sage_const_2 *r - _sage_const_4  - _sage_const_39 *tau) * c2)
        c.append(num / (_sage_const_8 *(r + _sage_const_1 )))
    return c

def twisted_polys(N, tau=QQ(_sage_const_1 )):
    A_list = [aesz_poly(n) for n in range(N)]
    c = cauchy_twist_coeffs(N, tau)
    return [
        sum(c[n-m] * A_list[m] for m in range(n + _sage_const_1 )) / QQ(_sage_const_64 )**n
        for n in range(N)
    ]

# theta_t operator
def theta_t_op(P, j):
    if j == _sage_const_0 :
        return P
    return sum(P[k] * k**j * t**k for k in range(P.degree() + _sage_const_1 ))

# Post-operator search
def search_post_operator(Bpolys, qvals,
                         dz=_sage_const_2 , dt=_sage_const_2 , zdeg=_sage_const_4 ,
                         nfit=_sage_const_20 , nverify=_sage_const_35 ):
    triples = [(i, j, h)
               for i in range(dz + _sage_const_1 )
               for j in range(dt + _sage_const_1 )
               for h in range(zdeg + _sage_const_1 )]

    print(f"  Search space: {len(triples)} unknowns, {nfit} equations")

    rows = []
    rhs = []

    for n in range(nfit):
        row = []
        for i, j, h in triples:
            if n < h:
                row.append(QQ(_sage_const_0 ))
            else:
                row.append(QQ(n-h)**i * theta_t_op(Bpolys[n-h], j)(_sage_const_1 ))
        rows.append(row)
        rhs.append(qvals[n])

    M = matrix(QQ, rows)
    y = vector(QQ, rhs)

    print(f"  Matrix: {M.nrows()} x {M.ncols()}, rank {M.rank()}")

    try:
        sol = M.solve_right(y)
    except ValueError as e:
        print(f"  No solution: {e}")
        return None

    # Check if solution is unique or if there's a kernel
    ker = M.right_kernel()
    print(f"  Kernel dimension: {ker.dimension()}")

    def candidate(n):
        out = QQt.zero()
        for coeff, (i, j, h) in zip(sol, triples):
            if coeff != _sage_const_0  and n >= h:
                out += coeff * QQ(n-h)**i * theta_t_op(Bpolys[n-h], j)
        return out

    # Verify unused q values
    success = True
    for n in range(nfit, min(nverify, len(qvals))):
        predicted = candidate(n)(_sage_const_1 )
        actual = qvals[n]
        if predicted != actual:
            rel = float(abs(predicted - actual) / abs(actual)) if actual != _sage_const_0  else float('inf')
            print(f"  FAIL at n={n}: rel error = {rel:.6e}")
            success = False
            break

    if success:
        print(f"  PASSED verification for n={nfit}..{min(nverify, len(qvals))-_sage_const_1 }")

        # Check if polynomials satisfy the P2.7 recurrence coefficientwise
        print("  Checking recurrence on polynomials...")
        rec_ok = True
        for n in range(_sage_const_2 , min(nverify - _sage_const_1 , len(Bpolys) - _sage_const_1 )):
            Qn1 = candidate(n+_sage_const_1 )
            Qn = candidate(n)
            Qn_1 = candidate(n-_sage_const_1 )
            Qn_2 = candidate(n-_sage_const_2 )
            # Use CORRECT monic recurrence
            residual = Qn1 - alpha(n)*Qn - beta(n)*Qn_1 - gamma(n)*Qn_2
            if residual != _sage_const_0 :
                print(f"    Recurrence FAILS at n={n}")
                rec_ok = False
                break
        if rec_ok:
            print("    Recurrence HOLDS coefficientwise!")

    if not success:
        return None
    return triples, sol, candidate


